import{_ as o,o as c,c as d,a5 as t}from"./chunks/framework.DJo0M80U.js";const m=JSON.parse('{"title":"Maven 常用命令","description":"","frontmatter":{"title":"Maven 常用命令","date":"2026-07-03T00:00:00.000Z","categories":["Java 快速入门"],"tags":["Java","构建运维","OneNote"],"lastUpdated":false},"headers":[],"relativePath":"posts/java快速入门/第七部分：构建与运维/01-Maven/Maven 常用命令.md","filePath":"posts/java快速入门/第七部分：构建与运维/01-Maven/Maven 常用命令.md"}'),p={name:"posts/java快速入门/第七部分：构建与运维/01-Maven/Maven 常用命令.md"};function l(i,e,a,n,r,s){return c(),d("div",null,[...e[0]||(e[0]=[t('<div><p>我们可以在</p><p><code>cmd</code></p><p>中通过一系列的 <code>maven</code> 命令来对我们的 <code>maven-helloworld</code> 工程进行编译、测试、运 行、打包、安装、部署。</p><ul><li>compile</li><li>compile</li></ul><p>是 <code>maven</code> 工程的编译命令，作用是将 <code>src/main/java</code> 下的文件编译为 <code>class</code> 文件输出到 <code>target</code> 目录下。</p><p><code>cmd</code></p><p>进入命令状态，执行 <code>mvn compile</code>，如下图提示成功： 查看</p><p><code>target</code></p><p>目录，<code>class</code> 文件已生成，编译完成。</p><ul><li>test</li><li>test</li></ul><p>是 <code>maven</code> 工程的测试命令 <code>mvn test</code>，会执行 <code>src/test/java</code> 下的单元测试类。</p><p><code>cmd</code></p><p>执行 <code>mvn test</code> 执行 <code>src/test/java</code> 下单元测试类，下图为测试结果，运行 <code>1</code> 个测试用例，全部成功。</p><ul><li>clean</li><li>clean</li></ul><p>是 <code>maven</code> 工程的清理命令，执行 <code>clean</code> 会删除 <code>target</code> 目录及内容。</p><ul><li>package</li><li>package</li></ul><p>是 <code>maven</code> 工程的打包命令，对于 <code>java</code> 工程执行 <code>package</code> 打成 <code>jar</code> 包，对于 <code>web</code> 工程打成 <code>war</code> 包。</p><ul><li>install</li><li>install</li></ul><p>是 <code>maven</code> 工程的安装命令，执行 <code>install</code> 将 <code>maven</code> 打成 <code>jar</code> 包或 <code>war</code> 包发布到本地仓库。 从运行结果中，可以看出： 当后面的命令执行时，前面的操作过程也都会自动执行，</p><p><code>Maven</code> <strong>指令的生命周期</strong><code>maven</code> 对项目构建过程分为三套相互独立的生命周期，请注意这里说的是“三套”，而且“相互独立”， 这三套生命周期分别是：</p><ul><li><code>Clean Lifecycle</code> 在进行真正的构建之前进行一些清理工作。</li><li><code>Default Lifecycle</code> 构建的核心部分，编译，测试，打包，部署等等。</li><li><code>Site Lifecycle</code> 生成项目报告，站点，发布站点。</li></ul><p><code>maven</code> <strong>的概念模型</strong><code>Maven</code> 包含了一个项目对象模型 <code>(Project Object Model)</code>，一组标准集合，一个项目生命周期</p><ul><li>(Project</li><li>Lifecycle)</li></ul><p>，一个依赖管理系统<code>(Dependency Management System)</code>，和用来运行定义在生命周期阶段</p><p><code>(phase)</code></p><p>中插件<code>(plugin)</code>目标<code>(goal)</code>的逻辑。</p><p>项目对象模型 <code>(Project Object Model)</code> 一个</p><p><code>maven</code></p><p>工程都有一个 <code>pom.xml</code> 文件，通过 <code>pom.xml</code> 文件定义项目的坐标、项目依赖、项目信息、 插件目标等。</p><p>依赖管理系统<code>(Dependency Management System)</code> 通过</p><p><code>maven</code></p><p>的依赖管理对项目所依赖的 <code>jar</code> 包进行统一管理。 比如：项目依赖</p><p><code>junit4.9</code></p><p>，通过在 <code>pom.xml</code> 中定义 <code>junit4.9</code> 的依赖即使用 <code>junit4.9</code>，如下所示是 <code>junit4.9</code> 的依赖定义：</p><p><code>\\&lt;!--</code></p><p>依赖关系</p><ul><li>--&gt;</li><li>&lt;dependencies&gt;</li><li>&lt;!--</li></ul><p>此项目运行使用 <code>junit</code>，所以此项目依赖</p><ul><li>junit --&gt;</li><li>&lt;dependency&gt;</li><li>&lt;!-- junit</li></ul><p>的项目名称</p><ul><li>--&gt;</li><li>&lt;groupId&gt;junit&lt;/groupId&gt;</li><li>&lt;!-- junit</li></ul><p>的模块名称</p><ul><li>--&gt;</li><li>&lt;artifactId&gt;junit&lt;/artifactId&gt;</li><li>&lt;!-- junit</li></ul><p>版本</p><ul><li>--&gt;</li><li>&lt;version&gt;4.9&lt;/version&gt;</li><li>&lt;!--</li></ul><p>依赖范围：单元测试时使用</p><ul><li>junit --&gt;</li><li>&lt;scope&gt;test&lt;/scope&gt;</li><li>&lt;/dependency&gt;</li></ul><p>一个项目生命周期<code>(Project Lifecycle)</code> 使用</p><p><code>maven</code></p><p>完成项目的构建，项目构建包括：清理、编译、测试、部署等过程，<code>maven</code> 将这些 过程规范为一个生命周期，如下所示是生命周期的各各阶段：</p><p><code>maven</code> 通过执行一些简单命令即可实现上边生命周期的各各过程，比如执行 <code>mvn compile</code> 执行编译、 执行</p><p><code>mvn clean</code></p><p>执行清理。</p><p>一组标准集合 <code>maven</code> 将整个项目管理过程定义一组标准，比如：通过 <code>maven</code> 构建工程有标准的目录结构，有标准的生命周期阶段、依赖管理有标准的坐标定义等。</p><p>插件<code>(plugin)</code>目标</p><ul><li>(goal)</li><li>maven</li></ul><p>管理项目生命周期过程都是基于插件完成的。</p><p><code>idea</code> <strong>开发</strong> <code>maven</code> <strong>项目</strong> 在实战的环境中，我们都会使用流行的工具来开发项目。</p><p><code>idea</code> <strong>的</strong> <code>maven</code> <strong>配置</strong><strong>打开</strong>**-****&gt;<strong><code>File</code></strong>-&gt;<strong><code>Settings</code></strong>-&gt;**<strong>配置</strong> <code>maven</code></p><p>依据图片指示，选择本地</p><p><code>maven</code></p><p>安装目录，指定 <code>maven</code> 安装目录下 <code>conf</code> 文件夹中 <code>settings</code> 配置文件。</p><p><code>idea</code> <strong>中创建一个</strong> <code>maven</code> <strong>的</strong> <code>web</code> <strong>工程</strong> 打开</p><p><code>idea</code></p><p>，选择创建一个新工程 选择</p><p><code>idea</code></p><p>提供好的 <code>maven</code> 的<code>web</code> 工程模板</p><p>点击</p><p><code>Next</code></p><p>填写项目信息</p><p>点击</p><p><code>Next</code></p><p>，此处不做改动。</p><p>点击</p><p><code>Next</code></p><p>选择项目所在目录</p><p>点击</p><p><code>Finish</code></p><p>后开始创建工程，耐心等待，直到出现如下界面。</p><p>手动添加 <code>src/main/java</code> 目录，如下图右键 <code>main</code> 文件夹-&gt;</p><p><code>NewDirectory</code> 创建一个新的文件夹命名为 <code>java</code>点击 <code>OK</code> 后，在新的文件夹 <code>java</code> 上右键-&gt;<code>Make Directory as</code>-&gt;<code>Sources Root</code></p><p><strong>创建一个</strong> <code>Servlet</code></p><ol><li><code>src/java/main</code> 创建了一个 <code>Servlet</code>，但报错</li><li>要解决问题，就是要将 <code>servlet-api-xxx.jar</code> 包放进来，作为 <code>maven</code> 工程应当添加 <code>servlet</code> 的坐标，从而导入它的 <code>jar</code></li><li>在 <code>pom.xml</code> 文件添加坐标</li></ol><p>直接打开 <code>hello_maven</code> 工程的 <code>pom.xml</code> 文件，再添加坐标添加 <code>jar</code> 包的坐标时，还可以指定这个 <code>jar</code> 包将来的作用范围。 每个 <code>maven</code> 工程都需要定义本工程的坐标，坐标是 <code>maven</code> 对 <code>jar</code> 包的身份定义，比如：入门程序的坐标定义如下： <code>\\&lt;!--</code>项目名称，定义为组织名<code>+</code>项目名，类似包名</p><ul><li>--&gt;</li><li>&lt;groupId&gt;com.itheima&lt;/groupId&gt;</li><li>&lt;!--</li></ul><p>模块名称</p><ul><li>--&gt;</li><li>&lt;artifactId&gt;hello_maven&lt;/artifactId&gt;</li><li>&lt;!--</li></ul><p>当前项目版本号，<code>snapshot</code> 为快照版本即非正式版本，<code>release</code> 为正式发布版本 <code>--\\&gt;</code><code>传智播客——专注于 </code>Java<code>、</code>.Net<code>和</code>Php`、网页平面设计工程师的培训</p><ul><li>&lt;version&gt;0.0.1-SNAPSHOT&lt;/version&gt;</li><li>&lt;packaging &gt;</li></ul><p>：打包类型</p><p><code>jar</code></p><p>：执行 <code>package</code> 会打成 <code>jar</code> 包</p><p><code>war</code></p><p>：执行 <code>package</code> 会打成 <code>war</code> 包</p><p><code>pom</code></p><p>：用于 <code>maven</code> 工程的继承，通常父工程设置为 <code>pom</code></p><p><strong>坐标的来源方式</strong> 添加依赖需要指定依赖 <code>jar</code> 包的坐标，但是很多情况我们是不知道 <code>jar</code> 包的的坐标，可以通过如下方式查询：</p><p><strong>从互联网搜索</strong></p><p><a href="http://search.maven.org/" target="_blank" rel="noreferrer">http://search.maven.org/</a><a href="http://mvnrepository.com/" target="_blank" rel="noreferrer">http://mvnrepository.com/</a> 网站搜索示例：</p><p><strong>依赖范围</strong><code>A</code> 依赖 <code>B</code>，需要在 <code>A</code> 的 <code>pom.xml</code> 文件中添加 <code>B</code> 的坐标，添加坐标时需要指定依赖范围，依赖范围包括：</p><ul><li><code>compile</code>：编译范围，指 <code>A</code> 在编译时依赖 <code>B</code>，此范围为默认依赖范围。编译范围的依赖会用在编译、测试、运行，由于运行时需要所以编译范围的依赖会被打包。</li><li><code>provided</code>：<code>provided</code> 依赖只有在当 <code>JDK</code> 或者一个容器已提供该依赖之后才使用， <code>provided</code> 依赖在编译和测试时需要，在运行时不需要，比如：<code>servlet api</code> 被 <code>tomcat</code> 容器提供。</li><li><code>runtime</code>：<code>runtime</code> 依赖在运行和测试系统的时候需要，但在编译的时候不需要。比如：<code>jdbc</code>的驱动包。由于运行时需要所以 <code>runtime</code> 范围的依赖会被打包。</li><li><code>test</code>：<code>test</code> 范围依赖 在编译和运行时都不需要，它们只有在测试编译和测试运行阶段可用，比如：<code>junit</code>。由于运行时不需要所以 <code>test</code>范围依赖不会被打包。</li><li><code>system</code>：<code>system</code> 范围依赖与 <code>provided</code> 类似，但是你必须显式的提供一个对于本地系统中 <code>JAR</code>文件的路径，需要指定 <code>systemPath</code> 磁盘路径，<code>system</code>依赖不推荐使用。</li></ul><p>在</p><p><code>maven-web</code></p><p>工程中测试各各 <code>scop</code>。 测试总结：</p><ul><li>默认引入 的 <code>jar</code> 包 <code>------- compile</code> 【默认范围 可以不写】（编译、测试、运行 都有效 ）</li><li><code>servlet-api</code> 、<code>jsp-api ------- provided</code> （编译、测试 有效， 运行时无效 防止和 <code>tomcat</code> 下 <code>jar</code> 冲突）</li><li><code>jdbc</code> 驱动 <code>jar</code> 包 <code>---- runtime</code> （测试、运行 有效 ）</li><li><code>junit ----- test</code> （测试有效）</li></ul><p>依赖范围由强到弱的顺序是：<code>compile\\&gt;provided\\&gt;runtime\\&gt;test</code></p><p><strong>项目中添加的坐标</strong></p><p><strong>设置</strong> <code>jdk</code> <strong>编译版本</strong> 本教程使用</p><p><code>jdk1.8</code></p><p>，需要设置编译版本为 <code>1.8</code>，这里需要使用 <code>maven</code> 的插件来设置： 在</p><p><code>pom.xml</code></p><p>中加入：</p><p>&lt;build&gt; &lt;plugins&gt; &lt;plugin&gt; &lt;groupId&gt;org.apache.maven.plugins&lt;/groupId&gt; &lt;artifactId&gt;maven-compiler-plugin&lt;/artifactId&gt; &lt;configuration&gt; &lt;source&gt;1.8&lt;/source&gt; &lt;target&gt;1.8&lt;/target&gt; &lt;encoding&gt;UTF-8&lt;/encoding&gt; &lt;/configuration&gt; &lt;/plugin&gt; &lt;/plugins&gt; &lt;/build&gt; <strong>编写</strong> <code>servlet</code> 在 <code>src/main/java</code> 中创建 <code>ServletTest</code>，￼</p><p>编写 jsp</p><p><strong>在</strong> <code>web.xml</code> <strong>中配置</strong> <code>servlet</code> <strong>访问路径</strong></p><p><strong>添加</strong> <code>tomcat7</code> <strong>插件</strong> 在</p><p><code>pom</code></p><p>文件中添加如下内容</p><p>此时点击</p><p><code>idea</code></p><p>最右侧 <code>Maven Projects</code>， 就可以看到我们新添加的</p><p><code>tomcat7</code></p><p>插件 双击</p><p><code>tomcat7</code></p><p>插件下 <code>tomcat7:run</code> 命令直接运行项目</p><p>也可以直接点击如图按钮，手动输入 <code>tomc7:run</code> 命令运行项目</p><p>点击后弹出如下图窗口</p><p><code>3.2.10</code><strong>运行结果</strong></p></div>',1)])])}const v=o(p,[["render",l]]);export{m as __pageData,v as default};
